function group(start){const color=board[start],todo=[start],seen=new Set([start]),lib=new Set();while(todo.length){const i=todo.pop();for(const j of neighbors(i)){if(board[j]===".")lib.add(j);else if(board[j]===color&&!seen.has(j)){seen.add(j);todo.push(j);}}}return {stones:[...seen],liberties:[...lib]};}
