for(const j of neighbors(i)){if(board[j]===(color==="X"?"O":"X")){const g=group(j);if(!g.liberties.length){for(const k of g.stones){board[k]=".";removed.push(k);}}}}
const own=group(i);if(!own.liberties.length)throw Error("suicide");captured[color]+=removed.length;
